import { describe, expect, it, vi } from 'vitest';

import {
  evaluate,
  parseExpression,
  renderTemplate,
  ruleToExpression,
  tryEvaluate,
} from './index.js';

const options = { budgetClock: () => 0 };
describe('sandbox attack corpus and budgets', () => {
  it.each([
    'eval("x")',
    'Function("x")',
    'new Function("x")',
    'with(x) {}',
    'globalThis.process',
    'process.env',
    'window.location',
    'import("x")',
    'vars.x = 1',
    'vars.x++',
    'vars.x; vars.y',
    '(()=>1)()',
    'vars.fn()',
    'vars["constructor"]',
    'vars.__proto__',
    'vars["proto" + "type"]',
    '{constructor: 1}',
    'parseJSON("{\\"__proto__\\":{}}")',
    'x => x',
    '1 "+" 2',
    '"unterminated',
    '"bad\\q"',
    '"bad\\uXY00"',
    '1 2',
    '[]()',
    '({x: 1, x: 2})',
    '{1:2}',
    'vars.["x"]',
  ])('rejects %s without host execution', (source) => {
    expect(tryEvaluate(source, { vars: {} }, options).ok).toBe(false);
  });
  it('rejects getters without invoking them and forbids host functions/prototypes', () => {
    const getter = vi.fn(() => 'leak');
    const object = Object.defineProperty({}, 'x', { get: getter });
    expect(tryEvaluate('vars.x', { vars: object }, options).ok).toBe(false);
    expect(getter).not.toHaveBeenCalled();
    expect(tryEvaluate('vars', { vars: () => null }, options).ok).toBe(false);
    expect(tryEvaluate('vars', { vars: new Date(0) }, options).ok).toBe(false);
    expect(
      tryEvaluate('vars', { vars: Object.create({ inherited: 1 }) as unknown }, options).ok,
    ).toBe(false);
  });
  it('does not mutate caller state or global prototypes', () => {
    const facts = { vars: { x: 1 } };
    tryEvaluate('vars["__proto__"].polluted', facts, options);
    expect(facts).toEqual({ vars: { x: 1 } });
    expect(Object.prototype).not.toHaveProperty('polluted');
  });
  it('enforces source, parse depth, steps, string, collection, output and elapsed-time limits', () => {
    expect(() => parseExpression('1'.repeat(2001))).toThrow('SOURCE_LIMIT');
    expect(() => parseExpression('('.repeat(40) + '1' + ')'.repeat(40))).toThrow('DEPTH_LIMIT');
    expect(() => parseExpression(Array(50).fill('1').join('+'))).toThrow('DEPTH_LIMIT');
    expect(() => evaluate('1 + 2', {}, { limits: { maxSteps: 2 }, ...options })).toThrow(
      'STEP_LIMIT',
    );
    expect(() => evaluate('"abcdef"', {}, { limits: { maxStringLength: 3 }, ...options })).toThrow(
      'STRING_INVALID',
    );
    expect(() => evaluate('[1,2]', {}, { limits: { maxCollectionLength: 1 }, ...options })).toThrow(
      'COLLECTION_LIMIT',
    );
    expect(() => evaluate('"abc"', {}, { limits: { maxOutputBytes: 2 }, ...options })).toThrow(
      'OUTPUT_LIMIT',
    );
    let clock = 0;
    expect(() => evaluate('1', {}, { budgetClock: () => clock++ * 100 })).toThrow('TIMEOUT');
    expect(() =>
      evaluate(
        'map(vars.items, x => x + 1)',
        { vars: { items: Array(100).fill(1) } },
        { ...options, limits: { maxSteps: 150 } },
      ),
    ).toThrow('STEP_LIMIT');
    expect(() => renderTemplate(Array(33).fill('{{1}}').join(''), {}, options)).toThrow(
      'TEMPLATE_INVALID',
    );
  });
  it('handles classic ReDoS patterns in the RE2 engine and rejects backreferences', () => {
    expect(
      evaluate(
        'regexTest(vars.text, "(a+)+$")',
        { vars: { text: 'a'.repeat(1000) + '!' } },
        options,
      ),
    ).toBe(false);
    expect(tryEvaluate('regexTest("aa", "(a)\\\\1")', {}, options)).toMatchObject({
      ok: false,
      error: { code: 'REGEX_INVALID' },
    });
  });
  it('rejects malformed and oversized rule trees before recursive schema evaluation', () => {
    expect(() => ruleToExpression({ all: [] })).toThrow();
    expect(() => ruleToExpression({ fact: 'vars.constructor', op: 'eq', value: 1 })).toThrow();
    let rule: unknown = { fact: 'vars.x', op: 'eq', value: 1 };
    for (let i = 0; i < 40; i++) rule = { not: rule };
    expect(() => ruleToExpression(rule)).toThrow('DEPTH_LIMIT');
  });
});

src/boundary-contracts.spec.ts.source:
import { describe, expect, it } from 'vitest';

import {
  analyzeExpression,
  compileExpression,
  createDefaultRegistry,
  evaluate,
  exprToRule,
  renameVariableExpression,
  renderTemplate,
  tryEvaluate,
} from './index.js';
import { age, formatCurrency } from './dates.js';
import { Budget, array, equal, numeric, text } from './runtime.js';
import { valueType } from './types.js';

const options = { budgetClock: () => 0 };
describe('expression resource and conversion boundaries', () => {
  it.each([
    [true, 'boolean'],
    [1, 'number'],
    ['a', 'string'],
    [null, 'null'],
    [[], 'array'],
    [{}, 'object'],
  ] as const)('classifies %j exactly', (value, type) => expect(valueType(value)).toBe(type));
  it('rejects objects with oversized keys and collections before exposing them to expressions', () => {
    const budget = new Budget({
      ...options,
      limits: { maxCollectionLength: 2, maxStringLength: 3 },
    });
    expect(() => budget.snapshot({ long: 1 })).toThrow('STRING_LIMIT');
    expect(() => budget.snapshot({ a: 1, b: 2, c: 3 })).toThrow('COLLECTION_LIMIT');
    expect(() => budget.snapshot([1, 2, 3])).toThrow('COLLECTION_LIMIT');
    expect(() => budget.snapshot(Symbol('invalid'))).toThrow('CONTEXT_INVALID');
    expect(() => numeric(null)).toThrow('TYPE_NUMBER');
    expect(() => text(1)).toThrow('TYPE_STRING');
    expect(() => array({})).toThrow('TYPE_ARRAY');
  });
  it('counts two, three and four byte UTF-8 output exactly', () => {
    for (const [value, bytes] of [
      ['é', 4],
      ['界', 5],
      ['😀', 6],
    ] as const) {
      expect(new Budget({ ...options, limits: { maxOutputBytes: bytes } }).output(value)).toBe(
        value,
      );
      expect(() =>
        new Budget({ ...options, limits: { maxOutputBytes: bytes - 1 } }).output(value),
      ).toThrow('OUTPUT_LIMIT');
    }
  });
  it('compares structured values with matching keys, lengths and array types', () => {
    expect(equal([1], { 0: 1 })).toBe(false);
    expect(equal({ a: 1 }, { b: 1 })).toBe(false);
    expect(equal([1], [1, 2])).toBe(false);
    expect(equal({ a: [null] }, { a: [null] })).toBe(true);
    expect(equal({ a: 1 }, { a: 2 })).toBe(false);
  });
  it.each(['"a"[8]', '[1][8]', '"a"["oops"]', '[1]["oops"]'])(
    'returns null for absent or non-index access %s',
    (source) => expect(evaluate(source, {}, options)).toBeNull(),
  );
  it.each(['{a:1}[true]', '{a:1}[null]'])('rejects invalid computed keys %s', (source) =>
    expect(tryEvaluate(source, {}, options)).toMatchObject({
      ok: false,
      error: { code: 'PROPERTY_INVALID' },
    }),
  );
  it('checks fresh compilation overrides and exposes safe failures from extensions', () => {
    const compiled = compileExpression('1 + 2', options);
    expect(compiled.evaluate()).toBe(3);
    expect(() => compiled.evaluate({}, { limits: { maxSourceLength: 1 } })).toThrow('SOURCE_LIMIT');
    expect(tryEvaluate('1', {}, { now: () => NaN })).toMatchObject({
      ok: false,
      error: { code: 'DATE_INVALID' },
    });
    const registry = createDefaultRegistry().register({
      name: 'broken',
      parameters: [],
      returns: 'null',
      minArgs: 0,
      maxArgs: 0,
      implementation: () => {
        throw new Error('private details');
      },
    });
    expect(tryEvaluate('broken()', {}, { ...options, registry })).toEqual({
      ok: false,
      error: { code: 'EVALUATION_FAILED', position: 0 },
    });
    expect(tryEvaluate('switch(1, 2, 3, 4, 5)', {}, options)).toMatchObject({
      ok: false,
      error: { code: 'ARGUMENT_COUNT' },
    });
    expect(tryEvaluate('toNumber("1e999")', {}, options)).toMatchObject({
      ok: false,
      error: { code: 'NUMBER_INVALID' },
    });
  });
  it('preserves registry implementations independently from interpreter short circuits', () => {
    const registry = createDefaultRegistry(),
      context = { budget: new Budget(options), now: 0, locale: 'en' as const, lambda: () => null };
    expect(registry.get('if').implementation([true, 'yes', 'no'], context)).toBe('yes');
    expect(registry.get('if').implementation([false, 'yes', 'no'], context)).toBe('no');
    expect(registry.get('switch').implementation([1, 1, 'yes', 'no'], context)).toBeNull();
    expect(() => registry.get('between').implementation([1, []], context)).toThrow(
      'ARGUMENT_INVALID',
    );
  });
  it('does not lose escaped string keys during renaming', () => {
    expect(
      renameVariableExpression('vars["old\\u004eame"] + vars.oldName', 'oldName', 'next'),
    ).toBe('vars["next"] + vars.next');
  });
  it.each(['vars.x == 1', 'vars.x != 1'])(
    'recognizes non-strict equality in builder conversion %s',
    (source) =>
      expect(exprToRule(source)).toMatchObject({
        fact: 'vars.x',
        op: source.includes('!=') ? 'neq' : 'eq',
        value: 1,
      }),
  );
  it.each(['(vars.x > 1) && vars.flag', '(vars.x > 1) || vars.flag', '!(1 + 2)'])(
    'retains an expression that cannot be represented as a rule %s',
    (source) => expect(exprToRule(source)).toEqual({ $expr: source }),
  );
  it('diagnoses incomplete collection and conditional calls without crashing', () => {
    expect(analyzeExpression('filter()').diagnostics).toEqual([
      { code: 'ARGUMENT_COUNT', position: 0 },
    ]);
    expect(analyzeExpression('find()').type).toBe('unknown');
    expect(analyzeExpression('find([] , x => true)').type).toBe('unknown');
    expect(analyzeExpression('if(true)').type).toBe('unknown');
    expect(analyzeExpression('if(true, 1, "x")').type).toBe('unknown');
  });
  it('enforces template size and escapes delimiter characters inside quoted expressions', () => {
    expect(() =>
      renderTemplate('12345', {}, { ...options, limits: { maxStringLength: 4 } }),
    ).toThrow('STRING_LIMIT');
    expect(() =>
      renderTemplate(
        '{{ x }}{{ x }}',
        { x: 'long' },
        { ...options, limits: { maxStringLength: 20 } },
      ),
    ).not.toThrow();
    expect(renderTemplate('{{ "a\\\"}}b" }}', {}, options)).toBe('a&quot;}}b');
    expect(renderTemplate('', {}, options)).toBe('');
  });
  it('rejects non-finite age clocks and enormous currencies', () => {
    expect(() => age('2000-01-01', NaN)).toThrow('DATE_INVALID');
    expect(() => formatCurrency(1e15, 'en')).toThrow('CURRENCY_INVALID');
  });
});

src/mutation-boundaries.spec.ts.source:
import { describe, expect, it } from 'vitest';

import { compileExpression, evaluate, tryEvaluate } from './index.js';

const options = { now: () => Date.parse('2026-10-03T12:00:00Z'), budgetClock: () => 0 };
describe('decision boundaries and isolation', () => {
  it.each([-1, 0, 1, 99, 100, 101])(
    'keeps inclusive and exclusive limits distinct at %i',
    (value) => {
      const facts = { vars: { value } };
      expect(evaluate('vars.value >= 0 && vars.value < 100', facts, options)).toBe(
        value >= 0 && value < 100,
      );
      expect(evaluate('vars.value > 0 && vars.value <= 100', facts, options)).toBe(
        value > 0 && value <= 100,
      );
    },
  );
  it.each([
    [false, false],
    [0, 0],
    ['', ''],
    [null, 'fallback'],
  ] as const)('coalescing only substitutes null (%j)', (value, expected) => {
    expect(evaluate('vars.value ?? "fallback"', { vars: { value } }, options)).toBe(expected);
  });
  it('compiled decisions do not retain values between tenants or mutate input', () => {
    const expression = compileExpression('vars.allowed && vars.amount >= 100', options);
    const first = Object.freeze({ vars: Object.freeze({ allowed: true, amount: 100 }) });
    expect(expression.evaluate(first)).toBe(true);
    expect(expression.evaluate({ vars: { allowed: false, amount: 100 } })).toBe(false);
    expect(expression.evaluate(first)).toBe(true);
    expect(first.vars.amount).toBe(100);
  });
  it.each(['vars.constructor', 'vars.__proto__', 'vars["prototype"]'])(
    'rejects prototype access: %s',
    (source) => {
      expect(tryEvaluate(source, { vars: {} }, options).ok).toBe(false);
      expect(Object.hasOwn(Object.prototype, 'polluted')).toBe(false);
    },
  );
});

